parameters.jsCode:
// Recorta el error a lo que se puede leer de un vistazo en el celular. El
// detalle completo queda en Executions; acá va sólo lo necesario para decidir
// si hay que correr a mirar o puede esperar a mañana.
const e = $input.first().json;

const flujo = e.workflow?.name ?? 'desconocido';
const nodo = e.execution?.lastNodeExecuted ?? 'desconocido';
const mensaje = String(e.execution?.error?.message ?? 'sin mensaje').slice(0, 300);
const url = e.execution?.url ?? '';

return [{ json: { flujo, nodo, mensaje, url } }];

parameters.jsonBody:
